-- john-wesley -- PARTE 3 de 3. Ejecuta las partes EN ORDEN.

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'john-wesley',
  40,
  'Relaciones problemáticas (2/3)',
  $lira$[{"type": "p", "text": "John reconoció que si las autoridades de la Iglesia de Inglaterra intentaban restringir alguna o todas estas actividades, los metodistas podrían verse obligados a abandonar la Iglesia y formar su propia denominación. Sin embargo, dejó claro que ese momento aún no había llegado. A Charles le disgustó que John siquiera abriera la puerta a la posibilidad de abandonar la Iglesia de Inglaterra en el futuro. Como resultado, abandonó la conferencia en protesta, declarando: «He terminado con las conferencias para siempre»."}, {"type": "p", "text": "John, sin embargo, se mantuvo firme en su postura de que independizaría a las sociedades metodistas antes de permitir que los líderes de la Iglesia de Inglaterra les dictaran lo que podían y no podían hacer. Se despidió de Charles con estas palabras: «Es probable que el punto concerniente a la Iglesia se resuelva rápidamente. Porque si debemos disentir o guardar silencio, todo está perdido. Adiós»."}, {"type": "p", "text": "Mientras continuaba sus viajes después de la conferencia, John descubrió que el mensaje de permanecer dentro de la Iglesia de Inglaterra no siempre había calado hondo entre los miembros de base de las sociedades metodistas. En su siguiente visita a Newcastle, descubrió que varias sociedades ya habían abandonado la iglesia, creyendo erróneamente que esta decisión contaba con la aprobación de John. John intentó corregir la impresión errónea que tenían los miembros sobre su opinión al respecto, pero comprendió que era solo cuestión de tiempo antes de que la situación llegara a un punto crítico y se produjera una escisión de la Iglesia de Inglaterra. Pero por el momento, John se recordó a sí mismo que, en realidad, no quería ser etiquetado como el fundador de una nueva denominación, sino ser reconocido como un reformador dentro de la iglesia estatal existente."}, {"type": "p", "text": "Más tarde, en 1755, John realizó una gira por Irlanda una vez más, alentado por las nuevas sociedades metodistas que surgían allí y tratando de ganar a los católicos para las costumbres metodistas."}, {"type": "p", "text": "Charles Wesley, por otro lado, pasó el año recorriendo Inglaterra, intentando revertir la decisión de su hermano al negarse a apoyar total e incondicionalmente a la Iglesia de Inglaterra. Fue una tarea ingrata, pues descubrió que muchos miembros de las sociedades que visitó ansiaban separarse y formar su propia denominación. Frustrado, Charles puso fin a sus años de predicador itinerante y se estableció en Bristol para supervisar las sociedades metodistas de la ciudad y escribir himnos."}, {"type": "p", "text": "Mientras Charles estaba dispuesto a cambiar sus prioridades para poder pasar más tiempo con su esposa, John no. Su matrimonio con Molly se había vuelto más tenso. Finalmente, Molly llegó al punto de no querer vivir más con John, y con el dinero que había heredado de su primer esposo, regresó a una vida independiente. John continuó predicando y organizando. En 1763, John redactó lo que se conocería como las Actas Mayores, un conjunto de declaraciones sobre las creencias y prácticas metodistas que servirían como referencia para la toma de decisiones durante muchos años. Una vez completado el documento, se entregó una copia a cada predicador laico metodista como guía para su comportamiento dentro de la sociedad."}, {"type": "p", "text": "John cargó ejemplares de las Grandes Minutas en sus alforjas y partió de nuevo a visitar las sociedades metodistas de toda Inglaterra. En 1764, a los sesenta y un años, registró en su diario los acontecimientos de un día típico en la carretera."}, {"type": "p", "text": "Monté a caballo poco después de las cuatro [de la mañana] y sobre las dos [de la tarde] prediqué en el mercado de Llanidloes [a unas 40] millas de Shrewsbury. A las tres cabalgamos a través de las montañas hasta Fountainhead… Montamos de nuevo sobre las siete. Nos perdimos y terminamos en el borde de un pantano… Un hombre honesto, montando al instante, galopó delante de nosotros, subiendo y bajando la colina, hasta que nos condujo a un camino que, según dijo, conducía directamente a Roes-fair. Cabalgamos hasta que otro nos encontró y nos dijo: \"No, este es el camino a Aberystwith... Deben regresar y cabalgar hasta ese puente de allá. El dueño de la casita cerca del puente nos indicó el siguiente pueblo... [Más tarde, pasadas las nueve de la noche,] tras vagar una hora por la montaña, a través de rocas, ciénagas y precipicios,... regresamos a la casita cerca del puente. [Estaba] llena de mineros borrachos y rugientes; y ni hierba, ni heno, ni maíz... Contratamos a uno de los mineros para que nos acompañara a Roes-fair, aunque estaba terriblemente borracho, hasta que cayó de bruces en un arroyo retumbante, y recuperó el sentido. Entre las once y las doce llegamos a la posada... [A la mañana siguiente descubrimos] que la mula tenía varios cortes y que mi yegua sangraba como un cerdo por una herida... hecha, al parecer, con una horca. Este arduo viaje fue uno de los muchos que John emprendió. De hecho, a su avanzada edad, aún recorría unos cinco mil kilómetros al año, predicando más de ochocientos sermones y animando a los cien predicadores a su cargo. Sin importar las circunstancias, John estaba decidido a predicar el evangelio a la gente común e incitarla a vivir una vida santa. Había recorrido un largo camino desde que, décadas atrás, conoció la fe de los moravos y dudó de su valía como cristiano. Ahora, su valía podía contarse en las vidas de los muchos hombres, mujeres y niños que, gracias a los esfuerzos de John, tenían fe en Jesucristo. Pasaron los años, cada uno tan ajetreado como el anterior. John finalmente envió a dos predicadores metodistas itinerantes a las colonias americanas para organizar las sociedades metodistas que estaban surgiendo allí. Hasta entonces, había eludido la posibilidad de expandirse al extranjero. Algunos metodistas habían emigrado a las islas del Caribe y fundado sociedades allí, al igual que soldados británicos destinados a servir en Canadá y otras colonias de Norteamérica. Pero la presión para organizar oficialmente estas sociedades había aumentado hasta que, en la conferencia anual de agosto de 1769, Richard Boardman y Joseph Pilmoor fueron enviados a Norteamérica con dinero para establecer un centro de reuniones metodista en Nueva York."}]$lira$::jsonb,
  1008
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'john-wesley',
  41,
  'Relaciones problemáticas (3/3)',
  $lira$[{"type": "p", "text": "Al mismo tiempo, y mucho más cerca de casa, John recibió con agrado la noticia del establecimiento de la primera escuela dominical para niños. Hannah Ball, una de sus seguidoras, fundó la escuela en High Wycombe, y además de las materias espirituales, se enseñaba a leer, escribir y aritmética. John pensó que la escuela era una idea maravillosa, pues creía que los cristianos deberían poder leer la Biblia por sí mismos en lugar de depender de otros para que les explicaran su contenido."}, {"type": "p", "text": "Durante la segunda mitad de 1770, George Whitefield realizó su séptimo viaje de predicación a Norteamérica. El 29 de septiembre, viajó de Portsmouth, Nuevo Hampshire, a Newburyport, Massachusetts. En el camino, se detuvo a predicar al aire libre en Exeter, Nuevo Hampshire. Mirando hacia arriba, oró: «Señor Jesús, estoy cansado de tu obra, pero no de tu obra. Si aún no he terminado mi carrera, permíteme ir a predicar por ti una vez más en los campos, sellar tu verdad, regresar a casa y morir»."}, {"type": "p", "text": "George Whitefield falleció a la mañana siguiente, agotado a los cincuenta y seis años. John quedó devastado al recibir la noticia en Inglaterra dos semanas después. Recordaba a George como un joven de diecisiete años en Oxford, inseguro de sí mismo, pero dispuesto a obedecer a Dios con todo su corazón. Desde entonces, la vida de George y la de John quedaron entrelazadas. Sin duda, ambos hombres se habían enfrentado a lo largo de los años por asuntos espinosos. A pesar de sus diferencias, habían logrado conservar el respeto mutuo. John tuvo el honor de predicar en Londres en tres servicios conmemorativos para George. Recordó a George como el hombre que inició el \"Gran Despertar\" al otro lado del océano Atlántico, en América. El texto de John para los sermones fue: \"¡Muera yo la muerte de los justos, y mi postrimería sea como la suya!\" (Números 23:10). John registró en su diario sus impresiones del primer servicio conmemorativo."}, {"type": "p", "text": "Una inmensa multitud se reunió desde todos los rincones del pueblo. Al principio temí que gran parte de la congregación no pudiera oír; pero a Dios le plació fortalecer mi voz, de modo que incluso los que estaban en la puerta oyeron con claridad. Fue un tiempo terrible. Todo estaba en silencio como la noche; la mayoría parecía profundamente afectada; y en muchos se produjo una impresión que espero no se borre pronto. La hora señalada para mi inicio en el Tabernáculo eran las cinco y media, pero a las tres estaba completamente lleno; así que comencé a las cuatro. Al principio, el ruido era muy fuerte, pero cesó cuando comencé a hablar; y mi voz se fortaleció tanto que todos los que estaban dentro podían oír, a menos que algún ruido fortuito la impidiera por unos instantes. ¡Oh, que todos oigan la voz de Aquel con quien se desenvuelven la vida y la muerte; y quien tan fuerte, con este toque inesperado, llama a todos sus hijos a amarse unos a otros!"}, {"type": "p", "text": "Al salir de la capilla en Tottenham Court Road donde se celebró el servicio conmemorativo, John pensó en uno de los dichos favoritos de George: \"Somos inmortales hasta que nuestro trabajo esté hecho\". Obviamente, el trabajo de George Whitefield estaba hecho, y John Wesley se preguntó cuánto tiempo más le concedería Dios."}]$lira$::jsonb,
  551
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'john-wesley',
  42,
  'Un trabajador incansable (1/3)',
  $lira$[{"type": "p", "text": "Aunque la mayoría de los hombres y mujeres de la época no llegaban a esa edad, el 17 de junio de 1770, John Wesley cumplió sesenta y siete años. En su cumpleaños, escribió la siguiente anotación en su diario:"}, {"type": "p", "text": "Me cuesta creer que hoy haya cumplido sesenta y ocho años [es decir, sesenta y siete]. ¡Qué maravillosos son los caminos de Dios! ¡Cómo me ha guardado desde niño! De los diez a los trece o catorce años, comí poco más que pan, y no en abundancia. Creo que esto, lejos de perjudicarme, sentó las bases de una salud duradera. Al crecer, como consecuencia de leer al Dr. Cheyne, opté por comer con moderación y beber agua. Este fue otro gran medio para mantener mi salud, hasta que… una fiebre me llevó al borde de la muerte, pero me dejó más sano que antes… Años después, estaba en la tercera etapa de tuberculosis;… a Dios le plació eliminarla también. Desde entonces no he conocido el dolor ni la enfermedad; ahora estoy más sano que hace cuarenta años. ¡Esto lo ha obrado Dios!"}, {"type": "p", "text": "Charles Wesley también seguía vivo, al igual que tres de las hermanas de John, Emilia, Martha y Anne, aunque al año siguiente Emilia moriría a los setenta y nueve años, cortando otro de los lazos con los días de vida en la rectoría de Epworth."}, {"type": "p", "text": "A pesar de su edad, John continuó con determinación, recopilando y preparando todo lo que había escrito para publicarlo en una obra colectiva. Cuando finalmente estuvo terminada, las Obras Colectivas ocuparon treinta y dos volúmenes. Con los años, John había ganado una considerable suma de dinero con sus escritos: hasta mil cuatrocientas libras al año. Sin embargo, incluso con este dinero, se mantuvo fiel a sus ideales de una vida sencilla. Guardó treinta libras para vivir, la misma cantidad que se había fijado en la universidad, y donó el resto a obras benéficas metodistas. Cuando le preguntaban por qué no guardaba un poco más para sus \"comodidades\" personales, John siempre respondía lo mismo: \"El dinero nunca se queda conmigo; me quemaría si lo hiciera. Lo tiro de mis manos lo antes posible, para que no se abra camino en mi corazón\"."}, {"type": "p", "text": "Mientras trabajaba en Inglaterra, John vigilaba atentamente lo que sucedía en las colonias americanas. En marzo de 1770, cinco colonos murieron cuando las tropas británicas abrieron fuego contra ellos en lo que se conocería como la Masacre de Boston. Ante la posibilidad de una rebelión a gran escala en América, muchos habitantes de las colonias recurrieron a las sociedades metodistas en busca de fuerza y estabilidad. En respuesta a este aumento en el número de personas que se unían a las sociedades, John envió a dos predicadores más a América desde Inglaterra. Eran Francis Asbury, de veintiséis años, y Thomas Coke, de veinticuatro. Los dos hombres provenían de orígenes muy diferentes. Thomas se graduó del Jesus College de Oxford y era clérigo ordenado de la Iglesia de Inglaterra, mientras que Francis provenía de una familia de clase baja de Wednesbury, escenario de algunos de los peores disturbios antimetodistas. Una vez que llegaron a las colonias, Thomas y Francis se hicieron cargo de la dirección de las sociedades metodistas en Nueva York y Filadelfia, liberando a Richard Boardman y Joseph Pilmoor para expandirse a las colonias del norte y del sur."}, {"type": "p", "text": "Mientras tanto, las cosas también cambiaban en Inglaterra. Las mujeres metodistas asumían un papel más importante en las sociedades. Esta era otra práctica que agravaba el conflicto entre los metodistas y la Iglesia de Inglaterra. John intentó suavizar la situación animando a las mujeres a usar sus dones de predicación, sin excederse lo suficiente como para ser acusadas de predicar, tal como lo había hecho su madre en Epworth cincuenta y ocho años antes. Esto no era fácil, y John le escribió a una \"predicadora\" metodista, Sarah Crosby, explicándole cómo debía proceder cuando grupos de hasta doscientas personas le rogaban que les predicara."}, {"type": "p", "text": "Cuando se vuelvan a encontrar, díganles simplemente: «Me ponen en una situación muy difícil. Los metodistas no permiten mujeres predicadoras; yo tampoco me considero así. Pero les diré abiertamente lo que siento en mi corazón»… No veo que hayan quebrantado ninguna ley. Continúen con calma y firmeza."}, {"type": "p", "text": "La multitud que se agolpaba para escuchar la predicación de John seguía creciendo, y en agosto de 1773, John predicó ante 32.000 personas, su mayor audiencia individual hasta entonces. «Quizás la primera vez que un hombre de setenta años era escuchado por treinta mil personas a la vez», anotó sobre la ocasión en su diario."}, {"type": "p", "text": "Tras la Masacre de Boston, las tensiones entre los colonos norteamericanos y los británicos se calmaron, pero volvieron a intensificarse en 1773, cuando el parlamento británico aprobó una ley que otorgaba a la Compañía de las Indias Orientales el monopolio de la venta de té en la colonia. Esta ley amenazó el sustento de muchos comerciantes locales de té, y se impidió que los barcos de la Compañía de las Indias Orientales atracaran y descargaran sus cargamentos en Nueva York y Filadelfia. En Boston, un grupo de ciudadanos locales tomó cartas en el asunto. El 16 de diciembre de 1773, el grupo, disfrazado de indios, abordó tres barcos de la Compañía de las Indias Orientales y arrojó cientos de cajas de té al puerto en un acto que se conocería como el Motín del Té de Boston."}]$lira$::jsonb,
  899
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'john-wesley',
  43,
  'Un trabajador incansable (2/3)',
  $lira$[{"type": "p", "text": "Por primera vez, un conflicto abierto entre Inglaterra y sus colonias americanas comenzó a vislumbrarse en el horizonte. Ante esta amenaza, muchos metodistas estadounidenses se dirigieron al norte, a Canadá, con la esperanza de evitar la guerra en las colonias del sur. En abril de 1775, la lucha entre los británicos y las colonias finalmente estalló en Concord y Lexington, Massachusetts. Al comienzo de la guerra, John se mostró sorprendentemente solidario con la causa rebelde. Incluso escribió una carta al secretario de estado para las colonias, Lord Dartmouth, en la que decía:"}, {"type": "p", "text": "Y aunque mis escritos sean de algún beneficio o no, no tienen por qué causar daño. Pues en el corazón de Su Señoría está el que otros ojos, salvo los suyos, los vean."}, {"type": "p", "text": "Todos mis prejuicios son contra los estadounidenses. Pues soy un clérigo, hijo de un clérigo, criado desde niño en las más altas nociones de obediencia pasiva y no resistencia. Y, sin embargo, a pesar de todos mis arraigados prejuicios, no puedo evitar pensar (si es que pienso) que un pueblo oprimido no pedía nada más que sus derechos legales, y eso de la manera más modesta e inofensiva que la naturaleza del asunto permitía."}, {"type": "p", "text": "Pero dejando esto de lado, dejando de lado toda consideración de lo correcto o lo incorrecto, pregunto: ¿es de sentido común utilizar la fuerza contra los estadounidenses? Una carta que tengo ante mí dice: «Cuatrocientos soldados regulares y cuarenta milicianos murieron en la última escaramuza». ¡Qué desproporción! ¡Y este es el primer ensayo de hombres inexpertos contra tropas regulares!"}, {"type": "p", "text": "Ya ve, mi Señor, sea lo que sea lo que se haya afirmado, estos hombres no se amedrentarán. Y parece que no serán conquistados tan fácilmente como se imaginó al principio. Probablemente disputarán cada centímetro de terreno y, si mueren, morirán a espada. De hecho, algunos de nuestros valientes oficiales dicen: «Dos mil hombres librarán a América de estos rebeldes». No, ni veinte mil, ni quizás el triple, sean rebeldes o no. Son hombres tan fuertes como ustedes; son tan valientes como ustedes, si no mucho más valientes. Porque son todos entusiastas, entusiastas de la libertad. Son entusiastas serenos y deliberados. Y sabemos cómo este principio, inculcado en las almas más sensibles, nace del amor a la guerra, la sed de venganza y el desprecio por la muerte. Sabemos que los hombres animados por esto se lanzarán al fuego o se abalanzarán sobre la boca de un cañón."}, {"type": "p", "text": "«Pero no tienen experiencia en la guerra». ¿Y cuánta más tienen nuestras tropas? ¡Cuán pocos han visto una batalla! «Pero no tienen disciplina». Eso es un completo error. Ya tienen casi tanta como nuestro ejército. Y aprenderán más cada día. Así que en poco tiempo la comprenderán tan bien como sus asaltantes."}, {"type": "p", "text": "Sin embargo, tras muchas reuniones con su amigo, el escritor Samuel Johnson, John cambió de opinión sobre la guerra en las colonias y se convirtió en defensor de las políticas británicas en Norteamérica. Incluso tomó uno de los panfletos de Johnson titulado «Impuestos, no tiranía» y lo republicó bajo su propio nombre con el título «Un discurso sereno a las colonias americanas». El panfleto declaraba que los colonos americanos no tenían derecho a luchar por su propia libertad mientras mantenían a los esclavos en cautiverio."}, {"type": "p", "text": "La publicación del panfleto provocó indignación pública, no por lo que decía el documento, sino porque John lo había copiado y publicado sin permiso. En respuesta a las críticas, John publicó otra edición del panfleto, reconociendo que su amigo Samuel Johnson lo había escrito originalmente. La indignación pública se calmó rápidamente."}, {"type": "p", "text": "Sin embargo, la predicción de John Wesley a Lord Dartmouth de que los colonos estadounidenses «probablemente disputarían cada centímetro de terreno y, si morían, morirían con la espada en la mano» resultó ser cierta. En julio de 1776, los colonos declararon su independencia de Gran Bretaña, y aunque la lucha contra los británicos no les iba bien, los colonos demostraban ser luchadores tenaces e impredecibles."}, {"type": "p", "text": "Mientras la guerra en las colonias americanas se intensificaba, John instó a los líderes metodistas a no tomar partido. Pero les hizo prácticamente imposible hacerlo al continuar imprimiendo sus panfletos antiamericanos y luego distribuirlos en las colonias. A pesar de la postura antiamericana de John, el número de personas que se unían a las sociedades metodistas en las colonias siguió creciendo, de 955 en 1775 a 4379 en 1777. Esto se debió a que los metodistas en Estados Unidos no sentían la misma lealtad hacia la Iglesia de Inglaterra y, en consecuencia, actuaban prácticamente como una iglesia independiente. De hecho, la situación de los metodistas en Norteamérica era un asunto que John Wesley no podía ignorar indefinidamente, aunque en aquel momento otros asuntos internos resultaban más urgentes."}, {"type": "p", "text": "Uno de estos asuntos, que le ocupó mucho tiempo a John, fue la construcción de una nueva capilla metodista en Londres. Para 1776, era evidente que la capilla de la fundición estaba vieja y deteriorada, y necesitaba ser reemplazada. John hizo un llamamiento a las sociedades metodistas de toda Inglaterra para que aportaran fondos para la construcción de una nueva capilla que sirviera como sede del metodismo. El dinero empezó a llegar a raudales, y el 21 de abril de 1777, bajo una lluvia torrencial, John colocó la primera piedra de la nueva estructura, que se llamaría Capilla de Wesley. La nueva capilla se situó en un terreno de un acre en Royal Row (City Road), donde anteriormente había molinos de viento, y a unos cincuenta metros al norte de la fundición. Durante los meses siguientes, John supervisó la construcción de la nueva capilla hasta su inauguración oficial el 1 de noviembre de 1778. El edificio era una capilla grande y sencilla con capacidad para dos mil personas. Junto a la capilla había una casa donde John viviría."}]$lira$::jsonb,
  964
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'john-wesley',
  44,
  'Un trabajador incansable (3/3)',
  $lira$[{"type": "p", "text": "Al mismo tiempo que se construía la Capilla de Wesley, John tenía otro proyecto en mente: la publicación de una revista metodista a la que llamó Revista Arminiana. La publicación estaba diseñada para promover las ideas metodistas y refutar el pensamiento calvinista. John mismo escribió muchos de los artículos de la revista. Uno de los primeros que escribió fue sobre el viejo Jeffrey, el fantasma que había rondado la rectoría de Epworth durante su juventud. Dos años después, en 1780, John publicó \"Una colección de himnos para el uso de los metodistas\". El himnario consistía en 525 himnos: siete escritos por Isaac Watts, uno por Samuel, el hermano de John, otro por su padre, diecinueve eran himnos alemanes que John había traducido, dieciséis escritos por él mismo y el resto eran obras de su hermano Charles. Fue un gran día para los hermanos ver tantas de sus palabras impresas, ya que ambos creían que los himnos tenían el poder de arraigarse en los corazones incluso de los oyentes más analfabetos. La mayoría de los himnos del nuevo himnario ya se habían publicado de alguna forma, pero John, con su habitual pragmatismo, presentó el himnario como \"no tan grande como para resultar engorroso o costoso; y... lo suficientemente grande como para contener un número de himnos que no se desgastaría fácilmente\"."}, {"type": "p", "text": "Un año después, en octubre de 1781, John regresó a Londres tras un viaje de predicación a Bristol y se enteró del fallecimiento de su esposa. La pareja había vivido separada durante muchos años, y John sintió una profunda tristeza por su fallecimiento."}, {"type": "p", "text": "Para entonces, John era un anciano y anticipaba su propia muerte en cualquier momento, sobre todo porque ya había vivido más que sus padres. Pero en su septuagésimo noveno cumpleaños seguía en plena forma, y anotó en su diario:"}, {"type": "p", "text": "Cumplí ochenta años [es decir, setenta y nueve], pero, bendito sea Dios, mi tiempo no es trabajo ni tristeza. No siento más dolor ni achaques físicos que a los veinticinco. Esto aún lo atribuyo (1) al poder de Dios, que me capacita para lo que me llama a hacer; (2) a que sigo viajando seis mil o ocho mil kilómetros al año; (3) a que duermo, de día o de noche, cuando quiero; (4) a que me levanto a una hora determinada; y (5) a mi constante predicación, sobre todo por la mañana."}, {"type": "p", "text": "Luego Juan añadió:"}, {"type": "p", "text": "Por último, la serenidad de ánimo. Siento y me aflijo, pero, por la gracia de Dios, no me inquieto por nada. Aun así, «la ayuda que se da en la tierra, él la hace él mismo». Y esto lo hace en respuesta a muchas oraciones."}, {"type": "p", "text": "Un compañero predicador, John Hampson, escribió una descripción del anciano John Wesley. Lo describió como un hombre sorprendentemente fuerte y musculoso para su edad, con «un cuerpo estrecho y trenzado, un abrigo con un pequeño cuello alto, sin hebillas en las rodillas, sin seda ni terciopelo en ninguna parte de su vestimenta, y una cabeza blanca como la nieve, lo que daba la impresión de algo primitivo y apostólico; mientras que un aire de pulcritud y limpieza se extendía por toda su persona»."}, {"type": "p", "text": "Incluso después de cumplir ochenta años, John no abandonó su incansable jornada de predicación. Permitía que sus amigos le compraran un carruaje, pero la mayoría de las veces se apoderaba de uno de los caballos que tiraban del carruaje y se adelantaba. Nada le resultaba más estimulante que un buen paseo a caballo de ochenta kilómetros o más. Mientras John recorría Inglaterra, Irlanda y Gales, las colonias americanas nunca dejaban de preocuparle. Con la ayuda de los franceses, los rebeldes estadounidenses en las colonias ganaron su lucha por la libertad, y Gran Bretaña reconoció a regañadientes su independencia. Este resultado sorprendió a John, quien había llegado a creer que Gran Bretaña luchaba por una causa justa. Sin embargo, decidió centrarse en el futuro y en lo que sucedería con los metodistas en Estados Unidos, quienes aún formaban parte oficialmente de la Iglesia de Inglaterra. Preguntas sobre el tema rondaban la mente de John. ¿Debían los metodistas en Estados Unidos seguir sujetos a las leyes de la Iglesia inglesa y al gobierno del rey Jorge III, quien no solo era el monarca inglés, sino también la cabeza de la Iglesia de Inglaterra? John sabía que no era el único que lidiaba con estas preguntas y que pronto habría que encontrar respuestas."}]$lira$::jsonb,
  736
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'john-wesley',
  45,
  'Activo hasta el final (1/4)',
  $lira$[{"type": "p", "text": "La década de 1780 finalmente puso fin a la persecución de los metodistas por parte de turbas enfurecidas. Ahora, dondequiera que iba, John recibía honores. Durante su último viaje a Irlanda, los alcaldes de Dublín y Cork le concedieron honores cívicos, y dondequiera que iba, John era un invitado codiciado. Desde Dublín, John realizó una gira de nueve semanas por sesenta pueblos y aldeas, predicando cien sermones, seis de ellos al aire libre, y uno en un lugar que, según él, era «grande pero no elegante, un establo»."}, {"type": "p", "text": "En 1784, John finalmente se enfrentó a la realidad de que tendría que planificar la supervivencia del metodismo tras su muerte. Decidió redactar una Escritura de Declaración, la cual firmó el 28 de febrero de 1784. La escritura definía legalmente la «Conferencia del pueblo llamado Metodista» y declaraba «cómo se continuaría su sucesión e identidad». El documento enumeraba los nombres de cien predicadores que supervisarían las sociedades y los bienes fiduciarios tras su muerte. John había estado preparando cuidadosamente a estos predicadores para esta responsabilidad, y continuó haciéndolo."}, {"type": "p", "text": "Cuatro meses después, en julio, John se sintió especialmente conmovido al visitar la escuela dominical de Robert Raikes. Raikes, un editor militante del Gloucester Journal , se había frustrado al informar sobre actividades delictivas y estaba convencido de que gran parte de lo que informaba era consecuencia de la pobreza y la falta de educación. En respuesta, fundó escuelas dominicales, al igual que Hannah Ball quince años antes, para enseñar a leer y escribir a los niños trabajadores de fábricas. Muchos de los padres de los niños se unieron a ellos en las lecciones dominicales. John registró en su diario sus reflexiones sobre lo que había visto."}, {"type": "p", "text": "Entré en la escuela dominical, que cuenta con doscientos cuarenta niños, a quienes varios maestros enseñan cada domingo y supervisa el párroco. Así, a muchos niños de una parroquia se les impide pecar abiertamente y se les enseña, al menos, un poco de buenos modales, además de leer la Biblia. Veo que estas escuelas surgen por todas partes. Quizás Dios tenga un propósito más profundo en esto de lo que los hombres imaginan. ¿Quién sabe si algunas de estas escuelas se convertirán en guarderías para cristianos?"}, {"type": "p", "text": "Cuando le preguntaron qué le parecía tan conmovedor de la escuela dominical, John respondió: «Reverencio a los jóvenes porque pueden ser útiles después de mi muerte. Cuiden de la nueva generación»."}, {"type": "p", "text": "Thomas Coke, a quien John había enviado a Norteamérica para ayudar a organizar las sociedades metodistas, regresó a Inglaterra. El 1 de septiembre de 1784, se dio un paso trascendental en Bristol con respecto a los metodistas en los recién independizados Estados Unidos. En la casa del Sr. Castleman, en la calle Dighton de Bristol, John impuso las manos sobre Thomas y lo ordenó superintendente de la «Iglesia de Dios bajo nuestro cuidado en Norteamérica». Además, John le encargó que regresara a Norteamérica y ordenara a Francis Asbury como su cosuperintendente, aunque advirtió que ninguno de los dos debía usar el título de obispo ."}, {"type": "p", "text": "Al regresar a Estados Unidos desde Inglaterra, Thomas llevaba consigo una carta de John Wesley a los metodistas estadounidenses que decía, en parte: «Como nuestros hermanos estadounidenses están ahora totalmente desvinculados tanto del Estado como de la jerarquía inglesa, no nos atrevemos a volver a involucrarlos ni con el uno ni con el otro. Ahora tienen plena libertad para seguir simplemente las Escrituras y la Iglesia primitiva; y consideramos que lo mejor es que se mantengan firmes en esa libertad con la que Dios los ha hecho tan singularmente libres»."}, {"type": "p", "text": "John continuó sus esfuerzos por liberar a los metodistas estadounidenses de cualquier conexión con la Iglesia de Inglaterra reescribiendo el Libro de Oración Común, llamándolo el Servicio Dominical de los Metodistas en Norteamérica. La nueva versión fue más breve y reemplazó los términos «sacerdote» y «obispo» por «superintendente» y «anciano». También omitió quince de los treinta y nueve artículos de fe, junto con la lista de días festivos que se celebraban en el calendario eclesiástico."}, {"type": "p", "text": "Mientras tanto, la situación avanzaba rápidamente en Norteamérica. Aunque John no lo consideró necesario, los metodistas estadounidenses decidieron votar sobre la ordenación de Francis Asbury y Thomas Coke antes de aceptarla. La votación fue unánime, pero la acción envió un mensaje claro a Inglaterra: si bien los metodistas estadounidenses serían leales a John Wesley como su fundador, pretendían vivir en conexión con él, no en subordinación. Al año siguiente, en la conferencia de Navidad de 1786, los líderes metodistas de Estados Unidos decidieron fundar una escuela para educar a los hijos de predicadores metodistas y huérfanos, similar al internado que John había establecido en Kingswood. Bautizaron la nueva institución como Cokesbury College, una fusión de los nombres de Coke y Asbury. Al año siguiente, John tomó una medida que aceleró la ruptura oficial entre los metodistas y la Iglesia de Inglaterra. Para proteger sus capillas y predicadores, John obtuvo licencias para ellas como centros de reunión disidentes. Esto significó que el metodismo ya no era una extensión de la Iglesia de Inglaterra, sino una denominación disidente. John tomó esta medida para evitar que los centros de reunión metodistas fueran absorbidos por la Iglesia de Inglaterra tras su muerte."}]$lira$::jsonb,
  868
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'john-wesley',
  46,
  'Activo hasta el final (2/4)',
  $lira$[{"type": "p", "text": "Al igual que con la ordenación de Francis Asbury y Thomas Coke, Charles Wesley se sintió disgustado por la decisión de su hermano de separarse de la iglesia madre. Esta decisión provocó una ruptura entre los dos \"gigantes del metodismo\", que lamentablemente no se resolvió antes de la muerte de Charles en marzo de 1788. John viajaba por el norte de Inglaterra en ese momento y no recibió la noticia de la muerte de Charles a tiempo para regresar al funeral. En lugar de celebrarse en la recién autorizada Capilla Metodista de City Road (la Capilla de Wesley), el funeral de Charles Wesley se celebró en St. Marylebone, una iglesia anglicana de Londres. Ocho ministros anglicanos llevaron el ataúd de Charles al cementerio, donde fue enterrado en tierra consagrada."}, {"type": "p", "text": "Charles Wesley dejó un legado de 6500 himnos, muchos de los cuales John publicó para él. Tres de sus himnos más populares fueron \"¡Escucha! Los ángeles anunciadores cantan\", \"Jesús, amante de mi alma\" y \"¡Oh, mil lenguas para cantar!\"."}, {"type": "p", "text": "Sabiendo que Charles comprendía la importancia y la urgencia de la predicación, John continuó su gira por el norte de Inglaterra, llegando a Bolton tres semanas después del funeral. Allí, mientras un coro infantil se preparaba para cantar uno de los himnos de Charles, John se puso de pie y leyó la primera estrofa:"}, {"type": "p", "text": "Ven, oh tú, Viajero desconocido,"}, {"type": "p", "text": "A quien aún sostengo, pero no puedo ver:"}, {"type": "p", "text": "Mi empresa anterior se fue,"}, {"type": "p", "text": "Y yo me quedo solo contigo."}, {"type": "p", "text": "A John le costó seguir leyendo, pero las palabras de su hermano lo conmovieron profundamente. En silencio, dejó el himnario a un lado, se sentó, se tapó la cabeza con las manos y lloró abiertamente por Charles."}, {"type": "p", "text": "El 1 de enero de 1790, John escribió en su diario: «Soy un anciano, decaído de pies a cabeza. Tengo la vista apagada; me tiembla mucho la mano derecha; tengo la boca caliente y seca todas las mañanas; tengo fiebre persistente casi todos los días; mis movimientos son débiles y lentos. Sin embargo, bendito sea Dios, no dejo de trabajar; todavía puedo predicar y escribir». John siguió levantándose a las cuatro de la mañana y viajó a Escocia y regresó antes de cumplir ochenta y siete años, el 17 de junio de 1790. Para entonces, sin embargo, pensaba que «probablemente no recuperaría las fuerzas en este mundo. Pero no siento dolor de pies a cabeza; solo parece que la naturaleza está agotada y, humanamente hablando, se hundirá cada vez más hasta que las cansadas fuentes de la vida se detengan»."}, {"type": "p", "text": "John también hizo otra visita a Epworth, aunque con sentimientos encontrados. La rectoría de Epworth ya no resonaba con los sonidos de su animada y talentosa familia; solo él y su hermana Martha seguían con vida. Aun así, el viaje tuvo momentos memorables. Los metodistas locales lo acompañaron a pie por los pantanos, de pueblo en pueblo, cantando al paso. John predicó en las plazas de los pueblos y saludó a amigos y admiradores por doquier con el verso: «Hijitos, amaos los unos a los otros»."}, {"type": "p", "text": "Más tarde, en 1790, John asistió a la conferencia anual metodista en Bristol. En la reunión, se incorporaron al registro oficial las últimas estadísticas sobre la membresía metodista. En Inglaterra había entonces 71.463 miembros metodistas; en Estados Unidos, 43.260; y en otras partes del mundo, incluyendo Escocia, el Caribe y Canadá, 5.350. Al concluir la conferencia, John, quien durante los últimos cuarenta y seis años había dirigido sus deliberaciones, firmó las actas. Su mano temblaba ahora, pero su visión de aumentar el número de metodistas era tan firme como siempre."}, {"type": "p", "text": "Durante el resto del año, John viajó y predicó en Gales, las Midlands, Lincolnshire, Escocia y la Isla de Wight. El 6 de octubre de 1790, al mediodía, predicó en un servicio al aire libre celebrado bajo un fresno en el cementerio de Winchelsea, Sussex, para que los trabajadores pudieran oírlo mientras almorzaban. El texto que eligió para su sermón fue: «El reino de los cielos se ha acercado; arrepentíos y creed en el evangelio»."}, {"type": "p", "text": "Para 1791, John estaba confinado en Londres, predicando en capillas donde era menos probable que se resfriara. En su vejez, John seguía preocupado por el estado del movimiento metodista, y anhelaba profundamente la unidad entre sus miembros. Expresó esto en una carta a América fechada el 1 de febrero, en la que escribió: «No pierdan la oportunidad de declarar a todos que los metodistas son un solo pueblo en todo el mundo, y que su firme determinación es continuar así, aunque se eleven montañas y se agite el océano, separándonos en vano»."}]$lira$::jsonb,
  766
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'john-wesley',
  47,
  'Activo hasta el final (3/4)',
  $lira$[{"type": "p", "text": "Aunque sus días de viaje habían terminado, John seguía interesado en el mundo que lo rodeaba. A principios del año nuevo, leyó la autobiografía de un esclavo africano llamado Gustavas Vassa. John había contribuido a pagar los gastos de publicación del libro, y leerlo por fin le produjo un gran placer."}, {"type": "p", "text": "En respuesta a lo que leyó en el libro, John dictó una carta a William Wilberforce, un metodista converso y miembro del Parlamento que defendía la causa de oponerse a la participación de Inglaterra en la esclavitud en cualquier parte del mundo. 24 de febrero de 1791"}, {"type": "p", "text": "MI SEÑOR : A menos que el Poder divino lo haya elevado a ser como Atanasio, contra"}, {"type": "h", "text": "Querido"}, {"type": "p", "text": "roundurn, no veo cómo podrá llevar a cabo su gloriosa empresa de oponerse"}, {"type": "p", "text": "a esa execrable villanía, que es"}, {"type": "p", "text": "de la naturaleza humana. A menos que Dios lo haya elevado"}, {"type": "p", "text": "el escándalo de la religión, de Inglaterra y"}, {"type": "p", "text": "precisamente para esto, se verá agotado por la oposición de hombres y demonios; pero si Dios está con usted, ¿quién podrá estar contra usted? ¿Acaso todos juntos son más fuertes que Dios? Oh, «no se cansen de hacer el bien». Continúen, en el nombre de Dios y con el poder de su fuerza, hasta que incluso la esclavitud americana, la más vil que jamás haya visto el sol, se desvanezca ante él."}, {"type": "p", "text": "Esta mañana, al leer un panfleto escrito por un africano pobre, me impactó especialmente esa circunstancia: que un hombre de piel negra, al ser agraviado o ultrajado por un blanco, no tenga derecho a ninguna reparación, pues en nuestras colonias la ley estipula que el juramento de un negro contra un blanco es nulo. ¡Qué vileza!"}, {"type": "p", "text": "Que Aquel que lo ha guiado desde su juventud continúe fortaleciéndolo en esto y en todas las cosas, es la oración de, querido señor, su afectuoso servidor, J W ."}, {"type": "h", "text": "Ohn Esley"}, {"type": "p", "text": "El final del invierno de 1791 fue duro, y John a menudo enfermaba de tos y resfriados. Cada episodio de enfermedad parecía debilitarlo un poco más, y John presentía que su fin se acercaba. La mañana del 1 de marzo, pidió pluma y tinta, pero no tenía fuerzas para escribir. Una líder metodista, Betsy Ritchie, le preguntó qué quería escribir. Con su única hermana sobreviviente, Martha, y la viuda de Charles, Sally, a su lado, John reunió las fuerzas que le quedaban y exclamó: «Lo mejor de todo es que Dios está con nosotros»."}, {"type": "p", "text": "Cuando Sally le humedeció los labios, repitió la acción de gracias que siempre recitaba después de comer: «Te damos gracias, Señor, por estas y todas tus misericordias; bendice a la Iglesia y al rey; y concédenos verdad y paz, por Jesucristo nuestro Señor, por los siglos de los siglos»."}, {"type": "p", "text": "John sobrevivió la noche, y en la mañana del miércoles 2 de marzo de 1791, los principales miembros de la Iglesia Metodista se reunieron junto a su lecho. John levantó los brazos y les impartió una bendición. \"¡Alzad, oh puertas, vuestras cabezas; y alzaos vosotras, puertas eternas, y entrará este heredero de la gloria!\". Estas palabras, dichas a los ochenta y siete años, John Wesley exhaló su último aliento. Fue un fallecimiento apropiado para un metodista: sin quejas, sin confesión de dolor, solo la gozosa anticipación de entrar en la presencia eterna de su Salvador."}, {"type": "p", "text": "El funeral de John se programó para el miércoles 9 de marzo, y el día antes del servicio, su cuerpo fue depositado en la capilla de City Road. Diez mil dolientes pasaron junto a su ataúd, ansiosos por ver por última vez a su líder."}, {"type": "p", "text": "Los organizadores del funeral, conscientes de que la capilla estaría abarrotada de dolientes, programaron en secreto el servicio para las cinco de la mañana. El reverendo John Richardson, uno de los clérigos que había ayudado a John durante casi treinta años, ofició el servicio. Al llegar a las palabras ceremoniales: «Por cuanto a Dios Todopoderoso le ha placido recibir el alma de nuestro querido hermano», con profundo sentimiento sustituyó la palabra «padre» por «hermano», y al hacerlo, la multitud reunida rompió a sollozar. John Wesley, el padre espiritual de tantos, por fin se sentía tranquilo. Durante su vida, había recorrido un cuarto de millón de millas a caballo, deteniéndose en el camino para predicar más de cuarenta mil sermones. Ofreció una forma sencilla de cristianismo a millones de personas que estaban fuera de la influencia de las iglesias de la época, y había dirigido un movimiento centrado en el amor de Dios y una vida santa que pronto se extendería por todo el mundo."}]$lira$::jsonb,
  761
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'john-wesley',
  48,
  'Activo hasta el final (4/4)',
  $lira$[{"type": "p", "text": "Fiel a su estilo, John había dado instrucciones meticulosas sobre cómo se dividiría su patrimonio. Dejó la mayor parte de su dinero al fondo general metodista; cuarenta libras a su hermana restante, Martha; y veinte chelines a cada uno de los \"seis hombres pobres\" que serían elegidos para llevar su ataúd. Aunque pidió que no hubiera luto, los organizadores del funeral ignoraron su petición y cubrieron la capilla de City Road con tela negra. Al terminar el funeral, la tela se cortó y se entregó a sesenta mujeres pobres para que se confeccionaran sus propios vestidos. Eso, al menos, a John le habría parecido bien."}, {"type": "p", "text": "En la primera conferencia metodista tras la muerte de John, se leyó en voz alta una carta que detallaba las instrucciones de John para la obra continua de los metodistas. En la carta, fechada en 1785, John advertía a quienes asumieran puestos de autoridad que no usaran su nuevo poder para imponerse a otros predicadores metodistas. Sus últimas palabras los instaron a seguir adelante con rectitud:"}, {"type": "p", "text": "No conozco otra manera de evitar semejante inconveniente que dejarles estas últimas palabras. Les suplico, por la misericordia de Dios, que nunca se valgan de la Escritura de Declaración para asumir superioridad alguna sobre sus hermanos, sino que permitan que todo siga su curso entre los itinerantes que decidan permanecer juntos exactamente igual que cuando yo estaba con ustedes, en la medida en que las circunstancias lo permitan. En particular, les suplico, si alguna vez me amaron, y si ahora aman a Dios y a sus hermanos, que no tengan acepción de personas al nombrar a los predicadores, al elegir a los niños para la Escuela Kingswood, al disponer de la contribución anual y el fondo de los predicadores, o de cualquier otro dinero público. Más bien, hagan todo con una sola mirada, como yo lo he hecho desde el principio. Continúen así, haciendo todo sin prejuicios ni parcialidad, y Dios estará con ustedes hasta el final."}]$lira$::jsonb,
  328
);


-- Cuadra el catalogo con lo cargado.
update public.books
set chapter_count = (select count(*) from public.chapters c where c.book_id = 'john-wesley'),
    minutes_to_read = 195
where id = 'john-wesley';

