select 'john-wesley', id, 'reflexionar',
       'A Wesley lo sacaron de una casa en llamas segundos antes de que se derrumbara, y toda su vida penso que se habia salvado para algo. Te ha pasado algo de lo que te salvaste por poco?',
       'Una frase basta. Nadie mas la va a leer.'
from public.chapters where book_id = 'john-wesley' and position = 0;

